<h1>امنیت حساب مدیریت</h1><div class="grid2 section"><section class="card"><h2>تغییر رمز مدیریت</h2><p class="small muted">با تغییر رمز، تمام نشست‌های مدیریت خودتان بسته می‌شوند. رمز و نشست‌های سایت اصلی جدا هستند.</p><?= $this->start('/me/password') ?><?= $this->field('current_password','رمز فعلی مدیریت','password') ?><?= $this->field('new_password','رمز جدید، حداقل ۸ نویسه','password') ?><button class="primary">تغییر رمز و خروج از مدیریت</button></form></section><section class="card"><h2>نشست‌های مدیریت شما</h2><?php foreach($rows as $row): ?><article><p><?= $row['id']===$this->actor['session_id']?'این نشست':'نشست دیگر' ?></p><p class="small ltr"><?= $this->h($row['agent_label']) ?></p><?= $this->start('/me/sessions/revoke') ?><input type="hidden" name="id" value="<?= $this->h($row['id']) ?>"><button class="secondary">بستن این نشست</button></form></article><?php endforeach; ?><?= $this->start('/me/sessions/revoke-others') ?><button class="primary section">بستن نشست‌های دیگر مدیریت</button></form></section>
<section class="card"><h2>شماره همراه حساب اصلی شما</h2><p><bdi><?= $this->h($this->actor['phone']??'هنوز تأیید نشده') ?></bdi></p><p class="small muted">با تأیید شماره، ورود پیامکی سایت به همین حساب داخلی متصل می‌شود؛ نشست مدیریت همچنان مستقل است.</p><?= $this->start('/me/phone/request') ?><?= $this->field('phone','شماره همراه برای تأیید یا تغییر','tel') ?><?= $this->field('current_password','رمز فعلی مدیریت','password') ?><button class="primary">درخواست کد تأیید شماره</button></form></section></div>
